\set ON_ERROR_STOP on
begin;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into moderators values('00000000-0000-0000-0000-000000000003');
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$ begin begin execute command;exception when others then raise notice 'PASS denied: %',label;return;end;raise exception 'FAIL allowed: %',label;end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into profiles values('00000000-0000-0000-0000-000000000001','Observer',now());
insert into observations(author_id,category,title,description,latitude,longitude) values('00000000-0000-0000-0000-000000000001','Safety','Trail ice','Ice near a public trail.',61.2181,-149.9003);
select pg_temp.assert_true((select latitude=61.22 and verification='unverified' from observations limit 1),'insert rounded and unverified');
select pg_temp.denied($q$select author_id from observations$q$,'reporter identity column private');
select pg_temp.denied($q$update observations set verification='reviewed'$q$,'owner cannot self-verify');
select pg_temp.denied($q$select moderate_report((select id from observations limit 1),'approve','Testing reason')$q$,'nonmoderator RPC blocked');
select pg_temp.denied($q$insert into observations(author_id,category,title,description,latitude,longitude) values('00000000-0000-0000-0000-000000000002','Safety','Spoofed report','Spoofed identity report.',61,-149)$q$,'spoofed author blocked');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
update observations set title='Unauthorized title';
select pg_temp.assert_true((select title='Trail ice' from observations limit 1),'other user cannot edit');
select pg_temp.assert_true((select count(*)=0 from profiles),'other profile hidden');
insert into report_flags(observation_id,reporter_id,reason) select id,'00000000-0000-0000-0000-000000000002','misleading' from observations limit 1;
select pg_temp.denied($q$insert into report_flags(observation_id,reporter_id,reason) select id,'00000000-0000-0000-0000-000000000002','misleading' from observations limit 1$q$,'duplicate flag blocked');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select moderate_report((select id from observations limit 1),'hide','Sensitive location');
select pg_temp.assert_true((select count(*)=1 from moderation_actions),'moderator audit recorded');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=0 from observations),'hidden observation unavailable anonymously');
select pg_temp.denied($q$select * from report_flags$q$,'flags private');
select pg_temp.assert_true((select count(*)=0 from moderators),'moderator membership private');
select pg_temp.denied($q$insert into observations(author_id,category,title,description,latitude,longitude) values('00000000-0000-0000-0000-000000000001','Safety','Anonymous report','Anonymous test report.',61,-149)$q$,'anonymous writes blocked');
select pg_temp.assert_true((select count(*)=0 from observation_media),'unpublished media unavailable');
select pg_temp.assert_true((select count(*)=0 from moderation_actions),'audit private');
select pg_temp.assert_true((select count(*)=0 from official_sources),'no unvalidated official sources');
select pg_temp.assert_true((select count(*)=0 from official_alerts),'no unvalidated official alerts');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into observations(author_id,category,title,description,latitude,longitude) select '00000000-0000-0000-0000-000000000001','Travel','Test report '||i,'Rate limit test description.',61,-149 from generate_series(1,4) i;
select pg_temp.denied($q$insert into observations(author_id,category,title,description,latitude,longitude) values('00000000-0000-0000-0000-000000000001','Travel','Sixth report','Rate limit test description.',61,-149)$q$,'sixth hourly report blocked');
rollback;
